CREATE TABLE companies (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL);
CREATE TABLE users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(200) NOT NULL);
CREATE TABLE memberships (user_id CHAR(36) NOT NULL, company_id CHAR(36) NOT NULL, role ENUM('HR','MANAGER') NOT NULL, PRIMARY KEY(user_id,company_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY,user_id CHAR(36) NOT NULL,expires_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE login_attempts (email_hash CHAR(64) PRIMARY KEY, attempts INT NOT NULL DEFAULT 0, window_start DATETIME NOT NULL);
CREATE TABLE employees (id CHAR(36) PRIMARY KEY,company_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,ssn VARCHAR(100) NOT NULL,job_title VARCHAR(120) NOT NULL,department VARCHAR(100) NOT NULL,site VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL DEFAULT '',active BOOLEAN NOT NULL DEFAULT TRUE,qr_token CHAR(64) NOT NULL UNIQUE,photo_id CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,ssn),UNIQUE(id,company_id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE competencies (id CHAR(36) PRIMARY KEY,company_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,category VARCHAR(80) NOT NULL,description TEXT NOT NULL, UNIQUE(company_id,name),UNIQUE(id,company_id),FOREIGN KEY(company_id) REFERENCES companies(id));
CREATE TABLE qualifications (id CHAR(36) PRIMARY KEY,company_id CHAR(36) NOT NULL,employee_id CHAR(36) NOT NULL,competency_id CHAR(36) NOT NULL,issuer VARCHAR(160) NOT NULL,valid_from DATE NOT NULL,expires_on DATE NULL,verification ENUM('PENDING','VERIFIED') NOT NULL DEFAULT 'PENDING',revoked BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(id,company_id),FOREIGN KEY(employee_id,company_id) REFERENCES employees(id,company_id),FOREIGN KEY(competency_id,company_id) REFERENCES competencies(id,company_id),CHECK(expires_on IS NULL OR expires_on >= valid_from));
CREATE TABLE documents (id CHAR(36) PRIMARY KEY,company_id CHAR(36) NOT NULL,employee_id CHAR(36) NOT NULL,qualification_id CHAR(36) NULL,kind ENUM('PHOTO','DIPLOMA') NOT NULL,original_name VARCHAR(200) NOT NULL,storage_name VARCHAR(100) NOT NULL,mime_type VARCHAR(80) NOT NULL,size_bytes INT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id,company_id) REFERENCES employees(id,company_id),FOREIGN KEY(qualification_id,company_id) REFERENCES qualifications(id,company_id));
CREATE TABLE api_tokens (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,company_id CHAR(36) NOT NULL,name VARCHAR(100) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id,company_id) REFERENCES memberships(user_id,company_id));
CREATE TABLE audit_events (id CHAR(36) PRIMARY KEY,company_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,action VARCHAR(120) NOT NULL,subject VARCHAR(180) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(company_id) REFERENCES companies(id),FOREIGN KEY(user_id) REFERENCES users(id),INDEX(company_id,created_at));
